import * as pulumi from "@pulumi/pulumi";
import * as k8s from "@pulumi/kubernetes";

const HELM_VERSION = "10.6.0";

export interface GiteaArgs {
  provider: k8s.Provider;
  namespace: string;
  domain: string;
  /** Database host (private endpoint) */
  dbHost: pulumi.Output<string>;
  /** Database port */
  dbPort: pulumi.Output<number>;
  /** Database username (created by DO DatabaseUser) */
  dbUser: pulumi.Output<string>;
  /** Database password (auto-generated by DO) */
  dbPassword: pulumi.Output<string>;
  /** Admin password (secret) */
  adminPassword: pulumi.Output<string>;
}

/**
 * Gitea — lightweight internal Git server for desired state storage.
 * ArgoCD reads from Gitea to reconcile cluster state.
 * Uses managed PostgreSQL with role-separated DatabaseUser.
 */
export class Gitea extends pulumi.ComponentResource {
  public readonly release: k8s.helm.v3.Release;
  public readonly ready: pulumi.Output<boolean>;

  constructor(name: string, args: GiteaArgs, opts?: pulumi.ComponentResourceOptions) {
    super("loop-runtime:platform:Gitea", name, {}, opts);

    // HOST in Gitea config expects "host:port" format
    const dbHostPort = pulumi.interpolate`${args.dbHost}:${args.dbPort}`;

    this.release = new k8s.helm.v3.Release(
      "gitea",
      {
        name: "gitea",
        chart: "gitea",
        version: HELM_VERSION,
        repositoryOpts: { repo: "https://dl.gitea.com/charts/" },
        namespace: args.namespace,
        createNamespace: false,
        values: {
          fullnameOverride: "gitea",
          image: { rootless: true },
          gitea: {
            admin: {
              username: "gitea_admin",
              password: args.adminPassword,
              email: "admin@loop-runtime.internal",
            },
            config: {
              server: {
                DOMAIN: `git.${args.domain}`,
                ROOT_URL: `https://git.${args.domain}/`,
                HTTP_PORT: 3000,
              },
              database: {
                DB_TYPE: "postgres",
                HOST: dbHostPort,
                NAME: "gitea",
                USER: args.dbUser,
                PASSWD: args.dbPassword,
                SSL_MODE: "require",
              },
              // In-memory cache (no Redis dependency)
              cache: { ADAPTER: "memory" },
              // Memory-based session store
              session: { PROVIDER: "memory" },
              // Memory-based queue
              queue: { TYPE: "level" },
            },
          },
          service: { http: { type: "ClusterIP", port: 3000 } },
          persistence: { enabled: true, size: "10Gi" },
          resources: {
            requests: { cpu: "100m", memory: "128Mi" },
            limits: { cpu: "500m", memory: "512Mi" },
          },
          // Disable embedded DB — using managed PostgreSQL
          postgresql: { enabled: false },
          "postgresql-ha": { enabled: false },
          // Disable embedded Valkey/Redis — using in-memory cache/session/queue
          "valkey-cluster": { enabled: false },
          valkey: { enabled: false },
          redis: { enabled: false },
          "redis-cluster": { enabled: false },
        },
      },
      { provider: args.provider, parent: this },
    );

    this.ready = this.release.status.apply((s) => s.status === "deployed");
    this.registerOutputs({ ready: this.ready });
  }
}
